@push('scripts')<script>
(() => { const open=id=>document.getElementById(id)?.showModal(); document.addEventListener('click',event=>{const opener=event.target.closest('[data-dialog-open]');if(opener){event.stopPropagation();open(opener.dataset.dialogOpen);return;}const closer=event.target.closest('[data-dialog-close]');if(closer)closer.closest('dialog')?.close();});document.querySelectorAll('.admin-user-row').forEach(row=>{row.addEventListener('click',event=>{if(!event.target.closest('button,a,input,select'))open(row.dataset.dialogOpen);});row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open(row.dataset.dialogOpen);}});});document.querySelectorAll('.admin-dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();}));if(new URLSearchParams(location.search).get('create')==='1')open('create-user-dialog');})();
</script>@endpush
